package com.shopsphere.dao;
import com.shopsphere.config.DBConnection;import java.sql.*;import java.util.*;
public class OrderDetailDAO{public Map<String,Object> findOrder(int userId,int orderId)throws SQLException{String q="SELECT o.order_id,o.total_amount,o.discount,o.payment_method,o.payment_status,o.order_status,o.created_at,a.address_line,a.city,a.state,a.pincode FROM orders o JOIN addresses a ON a.address_id=o.address_id WHERE o.user_id=? AND o.order_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(q)){s.setInt(1,userId);s.setInt(2,orderId);try(ResultSet r=s.executeQuery()){if(!r.next())return null;Map<String,Object>m=new LinkedHashMap<>();m.put("orderId",r.getInt(1));m.put("total",r.getBigDecimal(2));m.put("discount",r.getBigDecimal(3));m.put("paymentMethod",r.getString(4));m.put("paymentStatus",r.getString(5));m.put("orderStatus",r.getString(6));m.put("createdAt",r.getTimestamp(7));m.put("addressLine",r.getString(8));m.put("city",r.getString(9));m.put("state",r.getString(10));m.put("pincode",r.getString(11));return m;}}}public List<Map<String,Object>> findItems(int userId,int orderId)throws SQLException{List<Map<String,Object>>out=new ArrayList<>();String q="SELECT oi.product_id,p.name,oi.quantity,oi.unit_price FROM order_items oi JOIN orders o ON o.order_id=oi.order_id JOIN products p ON p.product_id=oi.product_id WHERE o.user_id=? AND oi.order_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(q)){s.setInt(1,userId);s.setInt(2,orderId);try(ResultSet r=s.executeQuery()){while(r.next()){Map<String,Object>m=new LinkedHashMap<>();m.put("productId",r.getInt(1));m.put("name",r.getString(2));m.put("quantity",r.getInt(3));m.put("unitPrice",r.getBigDecimal(4));out.add(m);}}}return out;}}
